 || 'T04ucGFyc2UocmVhZEZpbGVTeW5jKHBhdGguam9pbihyb290LCAic291cmNlLmpzb24iKSwgInV0ZjgiKSk7CmV4cG9ydCBkZWZhdWx0IGRlZmluZUNvbmZp'
 || 'Zyh7CiAgcGx1Z2luczogW3JlYWN0KCldLAogIHJlc29sdmU6IHsgYWxpYXM6IHsgIkBzaGVsbCI6IHBhdGguam9pbihyb290LCAic2hlbGwiKSB9IH0sCiAg'
 || 'ZGVmaW5lOiB7ICJwcm9jZXNzLmVudi5OT0RFX0VOViI6IEpTT04uc3RyaW5naWZ5KCJwcm9kdWN0aW9uIiksCiAgICAgICAgICAgIF9fT05FU0hPVF9HTE9C'
 || 'QUxfXzogSlNPTi5zdHJpbmdpZnkobWV0YWRhdGEuZ2xvYmFsKSB9LAogIGJ1aWxkOiB7IG91dERpcjogImFzc2V0cyIsIGVtcHR5T3V0RGlyOiB0cnVlLCBj'
 || 'c3NDb2RlU3BsaXQ6IGZhbHNlLAogICAgbGliOiB7IGVudHJ5OiBwYXRoLmpvaW4ocm9vdCwgbWV0YWRhdGEuZW50cnkpLCBuYW1lOiAiT25lc2hvdEFwcCIs'
 || 'IGZvcm1hdHM6IFsiaWlmZSJdLCBmaWxlTmFtZTogKCkgPT4gImFwcC5qcyIgfSwKICAgIHJvbGx1cE9wdGlvbnM6IHsgb3V0cHV0OiB7IGFzc2V0RmlsZU5h'
 || 'bWVzOiAic3R5bGUuY3NzIiB9IH0gfSwKfSk7Cg==')) || ''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE');
  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''GOV_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''GOV_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''GOV_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''GOV_APP'' AND "comment"=''oneshot-source:13_governance''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.GOV_APP FROM ''@__TARGET__.APP_STAGE/source/846a05587f73eba5/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:13_governance''; ALTER STREAMLIT __TARGET__.GOV_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
  stmts := ARRAY_APPEND(:stmts, REPLACE('BEGIN DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20071,''ONESHOT_SOURCE belongs to a different installation''); BEGIN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE''; IF (:present_count>0) THEN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE'' AND "comment"=''oneshot-source:13_governance''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE WORKSPACE __TARGET__.ONESHOT_SOURCE COMMENT=''oneshot-source:13_governance''; ALTER WORKSPACE __TARGET__.ONESHOT_SOURCE ADD LIVE VERSION FROM LAST; COPY FILES INTO ''snow://workspace/__TARGET__.ONESHOT_SOURCE/versions/live/'' FROM @__TARGET__.APP_STAGE/source/846a05587f73eba5/; END IF; END; EXCEPTION WHEN OTHER THEN NULL; END', '__TARGET__', :tgt));
  notes := ARRAY_APPEND(:notes, 'Editable source: ' || :tgt || '.ONESHOT_SOURCE. Existing workspace and app source are preserved on rerun.');
  notes := ARRAY_APPEND(:notes, 'OPEN THE APP after building: Snowsight > Projects > Streamlit > GOV_APP');
  cost_day := :cost_day + 0.10;
  cost_detail := ARRAY_APPEND(:cost_detail, 'Streamlit use is projected at 0.10 credits/day for light XS usage; source copying has additional serverless charges.');
        WHILE (:statement_index<ARRAY_SIZE(:stmts)) DO
          LET app_statement VARCHAR := :stmts[:statement_index]::VARCHAR;
          EXECUTE IMMEDIATE :app_statement;
          statement_index := :statement_index+1;
        END WHILE;
      ELSEIF (:existing_app[0]:comment::VARCHAR NOT IN ('oneshot-source:13_governance','Data Governance — generated from account discovery','Observability Monitor - generated from account discovery')) THEN
        completion_error := 'Existing app has an unrelated identity; its source was preserved.';
      END IF;
      IF (:completion_error='') THEN
        EXECUTE IMMEDIATE 'SHOW STREAMLITS IN SCHEMA ' || :tgt;
        app_ready := (SELECT COUNT(*)=1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"='GOV_APP');
        IF (:app_ready) THEN
          app_url := 'https://app.snowflake.com/' || LOWER(CURRENT_ORGANIZATION_NAME()) || '/' || LOWER(CURRENT_ACCOUNT_NAME()) || '/#/streamlit-apps/' || :tgt || '.GOV_APP';
          completion_status := IFF(:prior_result[0]:STATUS::VARCHAR='READY' AND COALESCE(:source_report:status::VARCHAR,'UNAVAILABLE') IN ('AVAILABLE','REVIEW_SOURCE_PROPOSAL','DISCOVERY_COMPLETE','AI_ASSISTED_SIGNAL_DISCOVERY'),'READY','APP_READY_REVIEW_REQUIRED');
        END IF;
      END IF;
      LET receipt_json VARCHAR := TO_JSON(:prior_result);
      LET discovery_json VARCHAR := TO_JSON(:source_report);
      LET persist_query VARCHAR := 'MERGE INTO ' || :tgt || '.INSTALLATION_STATUS target USING (SELECT 1 ID,? STATUS,PARSE_JSON(?) DETAILS,PARSE_JSON(?) DISCOVERY) source ON target.ID=source.ID WHEN MATCHED THEN UPDATE SET STATUS=source.STATUS,DETAILS=source.DETAILS,DISCOVERY=source.DISCOVERY,UPDATED_AT=CURRENT_TIMESTAMP() WHEN NOT MATCHED THEN INSERT VALUES(source.ID,source.STATUS,source.DETAILS,source.DISCOVERY,CURRENT_TIMESTAMP())';
      EXECUTE IMMEDIATE :persist_query USING(completion_status,receipt_json,discovery_json);
    END IF;
  EXCEPTION WHEN OTHER THEN
    completion_error := SQLERRM;
  END;
  result_rows := (SELECT IFF(:app_ready,:completion_status,'APP_BUILD_FAILED') AS STATUS,:app_url AS OPEN_APP_URL,
    IFF(:app_ready,'OPEN THE APP: click OPEN_APP_URL.' || IFF(:completion_status='READY',' No variable changes are required.',' The existing app is installed; review its discovery/build status before using incomplete results.'),'App installation failed: ' || :completion_error) AS NEXT_ACTION,
    :source_report:status::VARCHAR AS DISCOVERY_STATUS,:completion_error AS ERROR,:prior_result AS BUILD_DETAILS);
  RETURN TABLE(result_rows);
END;
$$;
